        self.search=tk.Entry(top,bg="#091525",fg=Glass.TEXT,insertbackground=Glass.TEXT,relief="flat",font=("Segoe UI",11));self.search.pack(fill="x",ipady=8,padx=8,pady=8);self.search.bind("<KeyRelease>",lambda e:self.render())
        self.grid=tk.Frame(self,bg=Glass.BG)
