    def _tk_callback_error(self, exc, val, tb):
        import traceback
        text="".join(traceback.format_exception(exc,val,tb))
        try: (ROOT / "afold_runtime_error.log").write_text(text, encoding="utf-8")
        except Exception: pass
        try: messagebox.showerror("AFold OS — ошибка", "Ошибка интерфейса: " + str(val) + "\n\nПодробности: afold_runtime_error.log", parent=self.root)
        except Exception: pass

    def ui_font(self,size=None,bold=False):return (self.store.config.get("font","Segoe UI"),size or self.store.config.get("font_size",10),"bold" if bold else "normal")
    def wallpaper(self):
        custom=self.store.config.get("custom_wallpaper","")
        if custom and Path(custom).exists():return None
        return {"blue":"#075a96","midnight":"#101827","aurora":"#183f58"}.get(self.store.config.get("wallpaper","blue"),"#075a96")
    def _widget_descends_from(self, widget, ancestor):
        """Return True when widget is inside ancestor without relying on Tk path strings."""
        try:
            w = widget
            while w is not None:
                if w is ancestor:
                    return True
                w = w.master
        except Exception:
            pass
        return False

    def _active_embedded_shortcut(self, event):
        """Route editing shortcuts to the AFold-embedded Word/Excel app."""
        try:
            widget = event.widget
            win = self.active_window
            app = getattr(win, "_embedded_app_instance", None) if win is not None else None
            app_root = getattr(app, "root", None) if app is not None else None
            if app is None or app_root is None or not self._widget_descends_from(widget, app_root):
                return None
            key = event.keysym.lower()
            ctrl = bool(event.state & 0x4)
            if not ctrl:
                return None
            if app.__class__.__name__ == "WordPro":
                actions = {
                    "a": app.select_all, "c": app.copy, "x": app.cut, "v": app.paste,
                    "z": app.undo, "y": app.redo, "b": app.toggle_bold,
                    "i": app.toggle_italic, "u": app.toggle_underline,
                    "s": app.save_document, "o": app.open_document,
                }
                fn = actions.get(key)
                if fn:
                    fn(); return "break"
            if app.__class__.__name__ == "SpreadsheetApp":
                actions = {
                    "a": app._select_all, "c": app._copy, "x": app._cut, "v": app._paste,
                    "z": app._undo, "y": app._redo, "s": app._save_file, "o": app._open_file,
                    "b": app._toggle_bold, "i": app._toggle_italic, "u": app._toggle_underline,
                }
                fn = actions.get(key)
                if fn:
                    fn(); return "break"
        except Exception:
            try: (ROOT / "afold_runtime_error.log").write_text(__import__("traceback").format_exc(), encoding="utf-8")
            except Exception: pass
        return None

    def _clipboard_text(self, widget):
        try:
            return widget.selection_get()
        except Exception:
            return ""

    def _copy_widget(self, widget):
        text = self._clipboard_text(widget)
        if text:
            self.root.clipboard_clear(); self.root.clipboard_append(text); self.root.update()

    def _cut_widget(self, widget):
        text = self._clipboard_text(widget)
        if text:
            self.root.clipboard_clear(); self.root.clipboard_append(text); self.root.update()
            if isinstance(widget, tk.Text): widget.delete("sel.first", "sel.last")
            elif isinstance(widget, tk.Entry): widget.delete("sel.first", "sel.last")

    def _paste_widget(self, widget):
        try:
            text = self.root.clipboard_get()
        except Exception:
            return
        try:
            if isinstance(widget, tk.Text):
                try: widget.delete("sel.first", "sel.last")
                except Exception: pass
                widget.insert("insert", text)
            elif isinstance(widget, tk.Entry):
                try: widget.delete("sel.first", "sel.last")
                except Exception: pass
                widget.insert("insert", text)
        except Exception:
            pass

    def _select_all_widget(self, widget):
        try:
            if isinstance(widget, tk.Text):
                widget.tag_add("sel", "1.0", "end-1c"); widget.mark_set("insert", "end-1c")
            elif isinstance(widget, tk.Entry):
                widget.select_range(0, "end"); widget.icursor("end")
        except Exception:
            pass

    def _text_widget_key(self, event):
        """Direct widget-level fallback. This runs before Tk's class bindings."""
        try:
            widget = event.widget
            key = event.keysym.lower()
            ctrl = bool(event.state & 0x4)
            if not ctrl:
                return None
            if key in {"a", "c", "x", "v"}:
                if key == "a": self._select_all_widget(widget)
                elif key == "c": self._copy_widget(widget)
                elif key == "x": self._cut_widget(widget)
                else: self._paste_widget(widget)
                return "break"
            routed = self._active_embedded_shortcut(event)
            if routed:
                return routed
        except Exception:
            pass
        return None

    def _shortcut_exact(self, event):
        """Reliable Ctrl shortcuts independent of Tk's event.state bitmask."""
        try:
            key=event.keysym.lower()
            routed=self._active_embedded_shortcut(event)
            if routed:
                return routed
            if key=="a": self._select_all_widget(event.widget)
            elif key=="c": self._copy_widget(event.widget)
            elif key=="x": self._cut_widget(event.widget)
            elif key=="v": self._paste_widget(event.widget)
            else: return None
            return "break"
        except Exception:
            return None

    def _text_context_menu(self, event):
        widget = event.widget
        menu = tk.Menu(self.root, tearoff=False)
        menu.add_command(label="Копировать", command=lambda: self._copy_widget(widget))
        menu.add_command(label="Вырезать", command=lambda: self._cut_widget(widget))
        menu.add_command(label="Вставить", command=lambda: self._paste_widget(widget))
        menu.add_separator()
        menu.add_command(label="Выделить всё", command=lambda: self._select_all_widget(widget))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()
        return "break"

    def _install_clipboard_bindings(self, widget):
        """Install reliable Windows-style editing plus a right-click menu."""
        if getattr(widget, "_afold_clipboard_ready", False):
            return widget
        widget._afold_clipboard_ready = True
        # Bind the concrete combinations as well as the generic handler. On some
        # Windows/Tk builds the generic Control-KeyPress state is inconsistent.
        for key in ("a","c","x","v","z","y","s","o","b","i","u"):
            widget.bind(f"<Control-KeyPress-{key}>", self._shortcut_exact, add="+")
        widget.bind("<Control-KeyPress>", self._text_widget_key, add="+")
        widget.bind("<Button-3>", self._text_context_menu, add="+")
        return widget

    def _scan_clipboard_widgets(self, parent=None):
        """Bind dynamically-created Entry/Text widgets (Word creates pages later)."""
        parent = parent or self.root
        try:
            for child in parent.winfo_children():
                if isinstance(child, (tk.Entry, tk.Text)):
                    self._install_clipboard_bindings(child)
                # Canvas is used by PyExcel; route its Ctrl shortcuts too.
                elif isinstance(child, tk.Canvas):
                    if not getattr(child, "_afold_canvas_shortcuts", False):
                        child._afold_canvas_shortcuts = True
                        child.bind("<Control-KeyPress>", self._text_widget_key, add="+")
                self._scan_clipboard_widgets(child)
        except Exception:
            pass

    def _start_clipboard_watcher(self):
        self._scan_clipboard_widgets()
        try: self.root.after(180, self._start_clipboard_watcher)
        except Exception: pass

    def _global_clipboard_shortcut(self, event):
        return self._text_widget_key(event)

    def _global_shortcut_dispatch(self, event):
        routed = self._active_embedded_shortcut(event)
        if routed:
            return routed
        return self._global_clipboard_shortcut(event)

    def _install_global_shortcuts(self):
        # Keep this as a final fallback; widget-level bindings have priority.
        for seq in ("<Control-a>", "<Control-c>", "<Control-x>", "<Control-v>",
                    "<Control-z>", "<Control-y>", "<Control-s>", "<Control-o>",
                    "<Control-b>", "<Control-i>", "<Control-u>"):
            self.root.bind_all(seq, self._global_shortcut_dispatch, add="+")

    def show_boot(self):
        self.root.configure(bg="#050b14");self.boot=tk.Frame(self.root,bg="#050b14");self.boot.pack(fill="both",expand=True)
        self.boot_logo=load_afold_logo(self.boot,92)
        if self.boot_logo: tk.Label(self.boot,image=self.boot_logo,bg="#050b14").pack(pady=(180,8))
        tk.Label(self.boot,text="AFold OS",fg="white",bg="#050b14",font=("Segoe UI",24,"bold")).pack()
        tk.Label(self.boot,text=f"{VERSION}  •  Build {BUILD}",fg="#8fa8c4",bg="#050b14",font=("Segoe UI",10)).pack(pady=8)
        self.dots=tk.Label(self.boot,text="",fg="white",bg="#050b14",font=("Segoe UI",16));self.dots.pack(pady=16)
        self.boot_stage=tk.Label(self.boot,text="Запуск AFold Core…",fg="#8fa8c4",bg="#050b14",font=("Segoe UI",10));self.boot_stage.pack()
        self.root.after(250,self.animate_boot,0)
    def animate_boot(self,i):
        try:
            if not self.root.winfo_exists(): return
            if i>60:
                if getattr(self,"boot",None) and self.boot.winfo_exists(): self.boot.destroy()
                # Activation is optional: every user can enter AFold OS normally.
                # Word/Excel and personalization are locked until activation.
                self.show_login()
                return
            self.dots.config(text="."*((i%3)+1));stages=["Запуск AFold Core…","Проверка хранилища…","Загрузка профиля…","Инициализация графической оболочки…","Подготовка рабочего стола…","Готово"]
            self.boot_stage.config(text=stages[min(len(stages)-1,i//11)]);self.root.after(500,self.animate_boot,i+1)
        except Exception:
            import traceback
            try: (ROOT / "afold_runtime_error.log").write_text(traceback.format_exc(),encoding="utf-8")
            except Exception: pass
            try: self.show_login()
            except Exception: pass

    # ========================= ACTIVATION =========================
    ACTIVATION_SECRET = "AFOLD-LOCAL-LICENSE-2026"
    DEMO_LICENSE = "AFOLD-BETA-2026-DEMO-125E912D"

    def is_activated(self):
        key = str(self.store.config.get("license_key", "")).strip().upper()
        return bool(self.store.config.get("activated", False)) and self._validate_license_key(key)

    def _validate_license_key(self, key):
        key = "-".join(key.replace(" ", "").upper().split("-"))
        if key == self.DEMO_LICENSE:
            return True
        parts = key.split("-")
        if len(parts) != 5 or parts[0] != "AFOLD" or parts[1] != "BETA" or parts[2] != "2026":
            return False
        prefix = "-".join(parts[:4])
        checksum = hashlib.sha256((prefix + "|" + self.ACTIVATION_SECRET).encode("utf-8")).hexdigest()[:8].upper()
        return parts[4] == checksum

    def show_activation_prompt(self):
        if getattr(self, "_activation_dialog_open", False):
            return False
        self._activation_dialog_open = True
        try:
            d = tk.Toplevel(self.root)
            d.title("Активация AFold OS")
            d.geometry("500x285")
            d.resizable(False, False)
            d.transient(self.root)
            d.grab_set()
            tk.Label(d, text="Активация AFold OS", font=("Segoe UI", 19, "bold")).pack(pady=(24, 8))
            tk.Label(d, text="Эта функция доступна после активации системы.", fg="#6b7280", font=("Segoe UI", 10)).pack()
            entry = tk.Entry(d, font=("Consolas", 12), justify="center", relief="solid", bd=1)
            entry.pack(fill="x", padx=45, pady=18, ipady=8)
            self._install_clipboard_bindings(entry)
            entry.focus_set()
            status = tk.StringVar(value="Введите лицензионный ключ")
            tk.Label(d, textvariable=status, fg="#6b7280").pack()
            def do_activate():
                key = entry.get().strip().upper()
                if self._validate_license_key(key):
                    self.store.config["activated"] = True
                    self.store.config["license_key"] = key
                    self.store.save()
                    status.set("Система активирована.")
                    try: d.grab_release(); d.destroy()
                    except Exception: pass
                    self._activation_dialog_open = False
                    self.show_toast("AFold OS активирована")
                else:
                    status.set("Неверный ключ активации")
                    entry.select_range(0, "end")
                    entry.focus_set()
            tk.Button(d, text="Активировать", command=do_activate, bg=Glass.BLUE, fg="white", relief="flat", bd=0, padx=28, pady=9, font=("Segoe UI", 10, "bold")).pack(pady=12)
            d.bind("<Return>", lambda e: do_activate())
            def close():
                self._activation_dialog_open = False
                try: d.grab_release(); d.destroy()
                except Exception: pass
            d.protocol("WM_DELETE_WINDOW", close)
            return True
        except Exception:
            self._activation_dialog_open = False
            return False

    def show_activation(self):
        for w in self.root.winfo_children():
            try: w.destroy()
            except Exception: pass
        self.activation = tk.Frame(self.root, bg="#050b14")
        self.activation.pack(fill="both", expand=True)
        logo = load_afold_logo(self.activation, 104)
        if logo:
            tk.Label(self.activation, image=logo, bg="#050b14").pack(pady=(105, 10))
        tk.Label(self.activation, text="AFold OS", fg="white", bg="#050b14", font=("Segoe UI", 30, "bold")).pack()
        tk.Label(self.activation, text="Активация системы", fg="#9eb3c9", bg="#050b14", font=("Segoe UI", 13)).pack(pady=(4, 14))
        tk.Label(self.activation, text="Введите ключ, чтобы разблокировать Word, Excel\nи персонализацию системы.", fg="#71869d", bg="#050b14", justify="center").pack(pady=8)
        entry = tk.Entry(self.activation, bg="#0b1625", fg="white", insertbackground="white", relief="flat", justify="center", font=("Consolas", 12), width=34)
        entry.pack(pady=12, ipady=9)
        self._install_clipboard_bindings(entry)
        status = tk.StringVar(value="Система не активирована")
        tk.Label(self.activation, textvariable=status, fg="#71869d", bg="#050b14").pack(pady=3)
        def activate():
            key = entry.get().strip().upper()
            if self._validate_license_key(key):
                self.store.config["activated"] = True
                self.store.config["license_key"] = key
                self.store.save()
                self.activation.destroy()
                self.show_login()
            else:
                status.set("Неверный ключ активации")
                entry.select_range(0, "end")
                entry.focus_set()
        tk.Button(self.activation, text="Активировать AFold OS", command=activate, bg=Glass.BLUE, fg="white", activebackground=Glass.BLUE2, relief="flat", bd=0, padx=28, pady=10, font=("Segoe UI", 11, "bold")).pack(pady=10)
        tk.Label(self.activation, text=f"{VERSION} • Build {BUILD}", fg="#526b83", bg="#050b14", font=("Segoe UI", 9)).pack(side="bottom", pady=24)
        entry.focus_set()
        entry.bind("<Return>", lambda e: activate())

    def show_login(self):
        self.login=tk.Frame(self.root,bg="#050b14");self.login.pack(fill="both",expand=True)
        self.login_logo=load_afold_logo(self.login,104)
        if self.login_logo: tk.Label(self.login,image=self.login_logo,bg="#050b14").pack(pady=(65,10))
        tk.Label(self.login,text="AFold OS",fg="white",bg="#050b14",font=("Segoe UI",28,"bold")).pack(pady=(0,15))
        tk.Label(self.login,text="Выберите пользователя",fg="#9eb3c9",bg="#050b14",font=("Segoe UI",11)).pack(pady=8)
        box=tk.Frame(self.login,bg="#0b1625",highlightthickness=1,highlightbackground=Glass.BORDER);box.pack(pady=18,padx=30)
        for user in self.store.users:
            tk.Button(box,text=f"●  {user['name']}",command=lambda n=user['name']:self.enter(n),bg="#14283d",fg="white",activebackground=Glass.BLUE,relief="flat",bd=0,font=("Segoe UI",12),width=28,pady=12).pack(padx=8,pady=4)
        tk.Button(self.login,text="＋ Добавить пользователя",command=self.add_user,bg="#0b1625",fg="#8fb9df",relief="flat",bd=0,pady=8).pack()
        tk.Label(self.login,text=f"AFold OS {VERSION} • Build {BUILD}",fg="#526b83",bg="#050b14",font=("Segoe UI",9)).pack(side="bottom",pady=25)
    def add_user(self):
        name=simpledialog.askstring("Пользователь","Имя нового пользователя:",parent=self.login)
        if name and name.strip():
            name=name.strip();self.store.users.append({"name":name,"color":Glass.BLUE});self.store.save();self.login.destroy();self.show_login()
    def enter(self,name):self.store.session["user"]=name;self.store.save();self.login.destroy();self.build_desktop();self.update_clock()
    def build_desktop(self):
        for w in self.root.winfo_children():w.destroy()
        self.desktop=tk.Frame(self.root,bg=self.wallpaper() or Glass.BG);self.desktop.pack(fill="both",expand=True)
        self.build_wallpaper();self.build_icons();self.build_taskbar()
        self.desktop.bind("<Button-3>",self.desktop_context)
        self.canvas.bind("<Button-3>",self.desktop_context)
        self.root.bind("<F5>",lambda e:self.build_icons())
        self._show_welcome(self.store.session.get("user",self.selected_user))
    def _show_welcome(self,name):
        if not hasattr(self,"desktop") or not self.desktop.winfo_exists(): return
        overlay=tk.Frame(self.desktop,bg="#020812")
        overlay.place(relx=0,rely=0,relwidth=1,relheight=1); overlay.lift()
        logo=load_afold_logo(overlay,96)
        if logo: tk.Label(overlay,image=logo,bg="#020812").pack(pady=(170,8))
        tk.Label(overlay,text="AFold OS",bg="#020812",fg="white",font=("Segoe UI",30,"bold")).pack(pady=(0,5))
        tk.Label(overlay,text=f"Добро пожаловать, {name}",bg="#020812",fg="white",font=("Segoe UI",22)).pack()
        tk.Label(overlay,text=f"{VERSION} • Build {BUILD}",bg="#020812",fg="#8fa8c4",font=("Segoe UI",10)).pack(pady=8)
        canvas=tk.Canvas(overlay,width=180,height=90,bg="#020812",highlightthickness=0); canvas.pack(pady=8)
        dots=[]
        for i in range(12): dots.append(canvas.create_oval(0,0,8,8,fill="#42b9ff",outline=""))
        state={"i":0}
        def animate():
            if not overlay.winfo_exists(): return
            state["i"]+=1
            cx,cy=90,45
            for j,item in enumerate(dots):
                a=(j*math.tau/12)+(state["i"]*0.20); r=30
                x=cx+math.cos(a)*r; y=cy+math.sin(a)*r
                canvas.coords(item,x-4,y-4,x+4,y+4)
                canvas.itemconfigure(item,fill="#ffffff" if j==(state["i"]%12) else "#42b9ff")
            self.root.after(45,animate)
        animate()
        self.root.after(5000,lambda: overlay.destroy() if overlay.winfo_exists() else None)

    def desktop_context(self,event):
        try:
            menu=tk.Menu(self.root,tearoff=0,bg="#101d2f",fg="white",activebackground=Glass.BLUE,activeforeground="white")
            menu.add_command(label="Создать папку",command=self.create_desktop_folder)
            menu.add_separator()
            menu.add_command(label="Обновить",command=lambda:self.build_icons())
            menu.add_command(label="Персонализация",command=self.open_settings)
            menu.add_separator()
            menu.add_command(label="Параметры экрана",command=self.open_settings)
            menu.add_separator()
            grid_state="✓  Выравнивание по сетке" if self.store.config.get("snap_to_grid",True) else "   Выравнивание по сетке"
            menu.add_command(label=grid_state,command=self.toggle_grid, state=("normal" if self.is_activated() else "disabled"))
            menu.tk_popup(event.x_root,event.y_root)
        finally:
            try: menu.grab_release()
            except Exception: pass

    def create_desktop_folder(self):
        name=simpledialog.askstring("Новая папка","Имя папки:",parent=self.root)
        if not name:
            return
        name=" ".join(name.strip().split())
        if not name:
            return
        # Do not allow path separators: this command creates a folder only on
        # AFold's own persistent desktop storage.
        if any(ch in name for ch in ("/", "\\", ":")) or name in (".", ".."): 
            messagebox.showwarning("Рабочий стол","Недопустимое имя папки.",parent=self.root)
            return
        target=DESKTOP_DIR / name
        try:
            target.mkdir(parents=True, exist_ok=False)
            self.store.save()
            self.build_icons()
            messagebox.showinfo("Рабочий стол",f"Папка «{name}» создана на рабочем столе.",parent=self.root)
        except FileExistsError:
            messagebox.showwarning("Рабочий стол","Такая папка уже существует.",parent=self.root)
        except Exception as exc:
            self._report_app_error("Создание папки",exc)

    def build_wallpaper(self):
        self.canvas=tk.Canvas(self.desktop,bg=self.wallpaper() or Glass.BG,highlightthickness=0)
        self.canvas.place(relwidth=1,relheight=1)
        custom=self.store.config.get("custom_wallpaper","")
        if custom and Path(custom).exists():
            try:
                from PIL import Image,ImageTk,ImageDraw,ImageFilter
                img=Image.open(custom).convert("RGB")
                img=img.resize((self.root.winfo_screenwidth(),self.root.winfo_screenheight()),Image.Resampling.LANCZOS)
                self._wall_img=ImageTk.PhotoImage(img)
                self.canvas.create_image(0,0,image=self._wall_img,anchor="nw")
            except Exception:
                self._draw_glass_wallpaper()
        else:
            self._draw_glass_wallpaper()
        w=self.root.winfo_screenwidth(); h=self.root.winfo_screenheight()
        self.canvas.create_text(w-18,h-88,anchor="se",text=f"{VERSION} • Build {BUILD}",
                               fill="#8ba5bd",font=("Segoe UI",8,"normal"))

    def _draw_glass_wallpaper(self):
        # 72 bands are intentionally used instead of per-pixel rendering:
        # this keeps startup lightweight on integrated graphics.
        w=self.root.winfo_screenwidth(); h=self.root.winfo_screenheight()
        top=(7,18,34); bottom=(18,47,70)
        for i in range(72):
            t=i/71
            rgb=tuple(int(top[c]*(1-t)+bottom[c]*t) for c in range(3))
            color="#%02x%02x%02x"%rgb
            y0=int(h*i/72); y1=int(h*(i+1)/72)+1
            self.canvas.create_rectangle(0,y0,w,y1,fill=color,outline=color)
        # Ambient color fields provide depth without costly blur filters.
        self.canvas.create_oval(w-620,-340,w+220,500,fill="#123f68",outline="")
        self.canvas.create_oval(w-520,-260,w+100,360,fill="#164d78",outline="")
        self.canvas.create_oval(-360,h-470,380,h+270,fill="#102f50",outline="")
        self.canvas.create_oval(w//3,h//3,w//3+520,h//3+520,fill="#0c2943",outline="")
        self.canvas.create_line(0,int(h*.72),w,int(h*.72),fill="#23415b",width=1)

    def build_icons(self):
        """Build desktop icons on the wallpaper canvas so they have no opaque rectangles."""
        if not hasattr(self, "canvas") or not self.canvas.winfo_exists():
            return
        # Remove only AFold desktop icon items; wallpaper and watermark stay intact.
        self.canvas.delete("desktop_icon")
        self.desktop_icon_widgets=[]
        self._desktop_item_keys={}

        size=self.store.config.get("icon_size",64)
        positions=self.store.config.setdefault("desktop_positions",{})
        keys=list(self.store.config.get("desktop_icons",DEFAULT_CONFIG["desktop_icons"]))
        try:
            folders=sorted([d for d in DESKTOP_DIR.iterdir() if d.is_dir()], key=lambda d:d.name.lower())
        except Exception:
            folders=[]

        all_items=[]
        for key in keys:
            app=self.app_map.get(key)
            if app:
                all_items.append((key,app.name,app.glyph,lambda a=app:self._desktop_open(a)))
        for folder in folders:
            key="folder:"+folder.name
            all_items.append((key,folder.name,"▰",lambda p=folder:self.open_desktop_folder(p)))

        # One-time migration of old desktop coordinates. Older builds could leave
        # icons at inconsistent positions; this gives the current build a clean
        # Windows-like grid while preserving later manual moves.
        changed=False
        if not self.store.config.get("desktop_layout_v3"):
            positions.clear()
            self.store.config["desktop_layout_v3"]=True
            changed=True
        for i,(key,name,glyph,command) in enumerate(all_items):
            if key not in positions:
                positions[key]=list(self._grid_position(24+(i//8)*100,24+(i%8)*92))
                changed=True
        if changed:
            self.store.save()

        icon_px=max(52,min(86,int(size)))
        glyph_size=max(22,min(42,int(icon_px*0.48)))
        label_font=self.ui_font(9)
        for key,name,glyph,command in all_items:
            x,y=positions.get(key,[24,24])
            tag=f"desktop_icon:{id((key,name))}"
            # Invisible hit target + text items: Canvas items have no background, so
            # changing the wallpaper can never leave blue/solid rectangles behind.
            hit=self.canvas.create_rectangle(x,y,x+94,y+92,outline="",fill="",tags=("desktop_icon",tag))
            icon_item=self.canvas.create_text(x+47,y+25,text=glyph,fill="white",
                                              font=("Segoe UI Symbol",glyph_size,"bold"),
                                              tags=("desktop_icon",tag))
            label_item=self.canvas.create_text(x+47,y+68,text=name,fill="white",
                                               font=label_font,width=88,justify="center",
                                               tags=("desktop_icon",tag))
            for item in (hit,icon_item,label_item):
                self._desktop_item_keys[item]=key
                self.canvas.tag_bind(item,"<Button-3>",lambda e,k=key,n=name:self.desktop_icon_context(e,k,n))
                self.canvas.tag_bind(item,"<Double-Button-1>",lambda e,cmd=command:cmd())
                self.canvas.tag_bind(item,"<ButtonPress-1>",lambda e,k=key:self.start_desktop_drag(e,k))
                self.canvas.tag_bind(item,"<B1-Motion>",lambda e,k=key:self.drag_desktop(e,k))
                self.canvas.tag_bind(item,"<ButtonRelease-1>",lambda e,k=key:self.end_desktop_drag(e,k))

    def _make_desktop_icon(self,key,name,glyph,x,y,command):
        # Kept for compatibility with older calls; desktop icons are now Canvas items.
        self.build_icons()

    def desktop_icon_context(self,event,key,name):
        menu=tk.Menu(self.root,tearoff=0,bg="#101d2f",fg="white",activebackground=Glass.BLUE,activeforeground="white")
        menu.add_command(label="Открыть",command=lambda:self._open_key(key))
        menu.add_command(label="Переименовать",command=lambda:self.rename_desktop_icon(key,name))
        menu.add_separator(); menu.add_command(label="Удалить с рабочего стола",command=lambda:self.remove_desktop_icon(key))
        menu.add_separator(); menu.add_command(label="Обновить",command=self.build_icons)
        menu.tk_popup(event.x_root,event.y_root)

    def _open_key(self,key):
        if key.startswith("folder:"):
            self.open_desktop_folder(DESKTOP_DIR/key.split(":",1)[1])
        else:
            app=self.app_map.get(key)
            if app:self._desktop_open(app)

    def rename_desktop_icon(self,key,old):
        if not self.is_activated():
            self.show_activation_prompt(); return
        name=simpledialog.askstring("Переименование","Новое имя:",initialvalue=old,parent=self.root)
        if name is None:return
        name=" ".join(name.strip().split())
        if not name:return
        names=self.store.config.setdefault("desktop_names",{}); names[key]=name; self.store.save(); self.build_icons()

    def remove_desktop_icon(self,key):
        if key.startswith("folder:"):
            return
        keys=self.store.config.get("desktop_icons",[])
        if key in keys: keys.remove(key)
        self.store.save(); self.build_icons()

    def _grid_position(self, x, y):
        # One stable grid.  Never derive the next position from the previous snapped
        # position while dragging; that was the source of the "jumping upward" bug.
        cell_w, cell_h = 100, 92
        return (max(24, round((x-24)/cell_w)*cell_w+24),
                max(24, round((y-24)/cell_h)*cell_h+24))

    def align_desktop_icons(self):
        positions=self.store.config.setdefault("desktop_positions",{})
        keys=list(self.store.config.get("desktop_icons",DEFAULT_CONFIG["desktop_icons"]))
        try:
            folders=sorted([d for d in DESKTOP_DIR.iterdir() if d.is_dir()], key=lambda d:d.name.lower())
        except Exception: folders=[]
        all_keys=keys+["folder:"+d.name for d in folders]
        for i,key in enumerate(all_keys):
            old=positions.get(key)
            if old is None:
                x=24+(i//8)*100; y=24+(i%8)*92
            else:
                x,y=old
            positions[key]=list(self._grid_position(x,y))
        self.store.save()
        self.build_icons()

    def toggle_grid(self):
        if not self.is_activated():
            self.show_activation_prompt(); return
        enabled=not self.store.config.get("snap_to_grid",True)
        self.store.config["snap_to_grid"]=enabled
        if enabled:
            self.align_desktop_icons()
        else:
            self.store.save(); self.build_icons()

    def start_desktop_drag(self,e,key):
        positions=self.store.config.setdefault("desktop_positions",{})
        # IMPORTANT: use the icon's real persisted/current position. The old code
        # defaulted to [24,24] when the position was not saved yet, so a simple click
        # could send every icon to the top-left corner.
        old=positions.get(key)
        if old is None:
            for item in self.canvas.find_withtag("desktop_icon"):
                # Find the item's tag containing the key and use its bounding box.
                tags=self.canvas.gettags(item)
                if any(t.endswith(":"+str(key)) for t in tags):
                    bbox=self.canvas.bbox(item)
                    if bbox:
                        old=[bbox[0],bbox[1]]
                    break
        if old is None:
            old=[24,24]
        self.drag_data={"key":key,"sx":e.x_root,"sy":e.y_root,
                        "ox":int(old[0]),"oy":int(old[1]),"moved":False,
                        "last_x":int(old[0]),"last_y":int(old[1])}

    def drag_desktop(self,e,key):
        d=getattr(self,"drag_data",None)
        if not d or d.get("key")!=key:return
        dx=e.x_root-d["sx"]; dy=e.y_root-d["sy"]
        if abs(dx)+abs(dy)<4:return
        d["moved"]=True
        nx=max(4,d["ox"]+dx); ny=max(4,d["oy"]+dy)
        positions=self.store.config.setdefault("desktop_positions",{})
        positions[key]=[int(nx),int(ny)]
        # Move the complete icon group as one unit.
        tag=f"desktop_key:{key}"
        # Canvas tags cannot safely use arbitrary persistent names, so move by
        # computing the delta from the last position for all items whose logical
        # key is stored in our drag map.
        ddx=int(nx)-d.get("last_x",d["ox"]); ddy=int(ny)-d.get("last_y",d["oy"])
        if ddx or ddy:
            for item in self.canvas.find_withtag("desktop_icon"):
                if getattr(self,"_desktop_item_keys",{}).get(item)==key:
                    self.canvas.move(item,ddx,ddy)
            d["last_x"]=int(nx); d["last_y"]=int(ny)

    def end_desktop_drag(self,e,key):
        d=getattr(self,"drag_data",None)
        if not d or d.get("key")!=key:return
        positions=self.store.config.setdefault("desktop_positions",{})
        if self.store.config.get("snap_to_grid",True):
            x,y=positions.get(key,[d.get("ox",24),d.get("oy",24)])
            positions[key]=list(self._grid_position(x,y))
            nx,ny=positions[key]
            ddx=nx-d.get("last_x",x); ddy=ny-d.get("last_y",y)
            if ddx or ddy:
                for item in self.canvas.find_withtag("desktop_icon"):
                    if getattr(self,"_desktop_item_keys",{}).get(item)==key:
                        self.canvas.move(item,ddx,ddy)
        self.store.save(); self.drag_data=None

    def open_desktop_folder(self,path):
        # Open the folder inside AFold's own Explorer.
        try:
            existing=self._windows_by_key.get("explorer")
            if existing is not None and existing.winfo_exists():
                existing.navigate(path);existing.deiconify() if not getattr(existing,"_afold_visible",True) else existing.lift()
                self.active_window=existing;return
            w=Explorer(self,path=path);self._register_window("explorer",w)
        except Exception as exc:
            self._report_app_error("Папка",exc)

    def _desktop_open(self, app):
        """Single launch path used by desktop, Start and taskbar."""
        try:
            if app.key in {"word", "excel"} and not self.is_activated():
                self.show_activation_prompt()
                return
            existing=self._windows_by_key.get(app.key)
            if existing is not None and existing.winfo_exists():
                if getattr(existing,"_afold_visible",True):
                    existing.lift();existing._raise_taskbar();self.active_window=existing
                else:
                    existing.deiconify()
                self._refresh_taskbar_states()
            else:
                result=app.command()
                if isinstance(result,LiquidWindow):
                    self._register_window(app.key,result)
            if self.start_menu is not None and self.start_menu.winfo_exists():
                self.start_menu.destroy();self.start_menu=None
        except Exception as exc:
            self._report_app_error(app.name, exc)
    def _report_app_error(self, name, exc):
        import traceback
        try:
            (ROOT / 'afold_runtime_error.log').write_text(traceback.format_exc(), encoding='utf-8')
        except Exception:
            pass
        try:
            messagebox.showerror('AFold OS', f'Не удалось открыть «{name}».\n\n{type(exc).__name__}: {exc}', parent=self.root)
        except Exception:
            pass
    def build_taskbar(self):
        # Floating dock: compact, centered and visually separated from the desktop.
        self.taskbar=tk.Frame(self.desktop,bg="#14283d",highlightthickness=1,
                              highlightbackground="#52718d",height=64)
        self.taskbar.place(relx=0.5,rely=1,anchor="s",relwidth=0.88,height=64,y=-12)
        self.taskbar_buttons={}
        self.taskbar.configure(cursor="arrow")
        tk.Button(self.taskbar,text="⊞",command=self.toggle_start,bg="#14283d",fg="white",
                  activebackground="#28577c",relief="flat",bd=0,
                  font=("Segoe UI Symbol",25),width=3,cursor="hand2").pack(side="left",padx=(8,2))
        self.taskbar_holder=tk.Frame(self.taskbar,bg="#14283d")
        self.taskbar_holder.pack(side="left",fill="y")
        pinned = list(self.store.config.get("taskbar_order", DEFAULT_CONFIG["taskbar_order"]))
        # Keep currently running unpinned applications visible, just like a normal taskbar.
        running = [k for k, win in self._windows_by_key.items()
                   if k not in pinned and win is not None and win.winfo_exists()]
        for key in pinned + running:
            self.make_task_button(self.taskbar_holder,key)
        # System tray. IMPORTANT: Tk pack(side="right") puts the first
        # packed widget at the far-right edge. Therefore the clock is packed
        # first so time/date is ALWAYS the last (rightmost) tray item.
        tray=tk.Frame(self.taskbar,bg="#14283d")
        tray.pack(side="right",fill="y")
        self.tray_status=tk.StringVar(value="")
        self.tray_lang=tk.StringVar(value=self.language_code())
        self.tray_battery=tk.StringVar(value="🔋")
        self.tray_net=tk.StringVar(value="🌐")
        self.tray_volume=tk.StringVar(value="🔊")
        self.clock=tk.StringVar(value=datetime.now().strftime("%H:%M\n%d.%m.%Y"))
        tk.Button(tray,textvariable=self.clock,command=self.show_calendar,bg="#14283d",fg="white",activebackground=Glass.PANEL2,relief="flat",bd=0,font=self.ui_font(9),padx=8).pack(side="right",fill="y")
        tk.Button(tray,text="🔔",command=self.notifications,bg="#14283d",fg="white",relief="flat",bd=0,font=("Segoe UI",10),padx=5).pack(side="right",fill="y")
        tk.Button(tray,text="▣",command=self.quick_actions,bg="#14283d",fg="white",relief="flat",bd=0,font=("Segoe UI",11),padx=5).pack(side="right",fill="y")
        tk.Button(tray,textvariable=self.tray_lang,command=self.cycle_language,bg="#14283d",fg="white",relief="flat",bd=0,font=("Segoe UI",9,"bold"),padx=7).pack(side="right",fill="y")
        tk.Button(tray,textvariable=self.tray_volume,command=self.open_volume_control,bg="#14283d",fg="white",activebackground=Glass.PANEL2,relief="flat",bd=0,font=("Segoe UI",9),padx=5).pack(side="right",fill="y")
        tk.Button(tray,textvariable=self.tray_net,command=self.show_network_info,bg="#14283d",fg="white",activebackground=Glass.PANEL2,relief="flat",bd=0,font=("Segoe UI",9),padx=5).pack(side="right",fill="y")
        tk.Button(tray,textvariable=self.tray_battery,command=self.show_battery_info,bg="#14283d",fg="white",activebackground=Glass.PANEL2,relief="flat",bd=0,font=("Segoe UI",9),padx=5).pack(side="right",fill="y")
        self._refresh_taskbar_states()
        self._update_tray()

    def make_task_button(self,parent,key):
        app=self.app_map.get(key)
        if not app:return None
        b=tk.Button(parent,text=app.glyph,bg="#14283d",fg="white",activebackground=Glass.BLUE,
                    relief="flat",bd=0,font=("Segoe UI",15,"bold"),width=3,cursor="hand2")
        b.pack(side="left",padx=2,pady=5);b._afold_key=key;self.taskbar_buttons[key]=b
        b._afold_hover_size=15
        b.bind("<Enter>",lambda e,btn=b:self._dock_hover(btn,True),add="+")
        b.bind("<Leave>",lambda e,btn=b:self._dock_hover(btn,False),add="+")
        b.bind("<ButtonPress-1>",lambda e,k=key:self.task_press(e,k))
        b.bind("<B1-Motion>",lambda e,k=key:self.task_drag(e,k))
        b.bind("<ButtonRelease-1>",lambda e,k=key:self.task_release(e,k))
        b.bind("<Button-3>",lambda e,k=key:self.taskbar_context_menu(e,k))
        return b

    def _dock_hover(self, button, entering):
        """Lightweight dock magnification: grow on hover and ease back on leave."""
        try:
            if not button.winfo_exists():
                return
            start = int(getattr(button, "_afold_hover_size", 15))
            target = 19 if entering else 15
            # Cancel the previous animation so rapid pointer movement never stacks timers.
            old = getattr(button, "_afold_hover_after", None)
            if old:
                try: button.after_cancel(old)
                except Exception: pass
            frames = 4
            def tick(step=1):
                if not button.winfo_exists():
                    return
                t = step / frames
                # Smooth ease-out curve; small changes keep the dock responsive.
                eased = 1 - (1 - t) * (1 - t)
                size = round(start + (target - start) * eased)
                button.configure(font=("Segoe UI", size, "bold"),
                                 bg=("#244a68" if entering else "#14283d"))
                button._afold_hover_size = size
                if step < frames:
                    button._afold_hover_after = button.after(12, lambda: tick(step + 1))
                else:
                    button._afold_hover_after = None
            tick()
        except Exception:
            pass

    def taskbar_context_menu(self, event, key):
        """Windows-style context menu for AFold taskbar buttons."""
        try:
            app = self.app_map.get(key)
            if app is None:
                return
            menu = tk.Menu(self.root, tearoff=0, bg="#0b1625", fg=Glass.TEXT,
                           activebackground=Glass.BLUE, activeforeground="white",
                           bd=0, relief="flat", font=self.ui_font(9))
            win = self._windows_by_key.get(key)
            running = win is not None and win.winfo_exists()
            visible = running and getattr(win, "_afold_visible", True)
            pinned = key in set(self.store.config.get("taskbar_order", []))

            if running:
                menu.add_command(text="Открыть", command=lambda k=key: self._taskbar_activate(k))
                menu.add_command(text="Свернуть", command=lambda w=win: self._taskbar_minimize_window(w))
                menu.add_separator()

            if pinned:
                menu.add_command(text="Открепить от панели задач", command=lambda k=key: self._set_taskbar_pinned(k, False))
            else:
                menu.add_command(text="Закрепить на панели задач", command=lambda k=key: self._set_taskbar_pinned(k, True))

            menu.add_separator()
            if running:
                menu.add_command(text="Закрыть окно", command=lambda w=win: self._close_taskbar_window(w))
            else:
                menu.add_command(text="Запустить", command=lambda k=key: self._taskbar_activate(k))
            menu.tk_popup(event.x_root, event.y_root)
            menu.bind("<FocusOut>", lambda _e: menu.destroy())
        except Exception as exc:
            self._report_app_error("Панель задач", exc)

    def _taskbar_minimize_window(self, win):
        try:
            if win is not None and win.winfo_exists():
                win.iconify()
                self._refresh_taskbar_states()
        except Exception as exc:
            self._report_app_error("Панель задач", exc)

    def _close_taskbar_window(self, win):
        try:
            if win is not None and win.winfo_exists():
                win.destroy()
        except Exception as exc:
            self._report_app_error("Панель задач", exc)

    def _set_taskbar_pinned(self, key, pinned):
        try:
            order = list(self.store.config.get("taskbar_order", []))
            if pinned:
                if key not in order:
                    order.append(key)
            else:
                order = [k for k in order if k != key]
            self.store.config["taskbar_order"] = order
            self.store.save()
            self.rebuild_desktop()
            self.show_toast("Закреплено на панели задач" if pinned else "Откреплено от панели задач")
        except Exception as exc:
            self._report_app_error("Панель задач", exc)

    def _ensure_task_button(self,key):
        if key in self.taskbar_buttons and self.taskbar_buttons[key].winfo_exists():
            return self.taskbar_buttons[key]
        if self.taskbar_holder is None or not self.taskbar_holder.winfo_exists():
            return None
        return self.make_task_button(self.taskbar_holder,key)

    def _refresh_taskbar_states(self):
        for key,b in list(self.taskbar_buttons.items()):
            if not b.winfo_exists():
                self.taskbar_buttons.pop(key,None);continue
            win=self._windows_by_key.get(key)
            if win is not None and win.winfo_exists():
                if getattr(win,"_afold_visible",False):
                    b.configure(bg=Glass.BLUE if self.active_window is win else Glass.PANEL2)
                else:
                    b.configure(bg=Glass.PANEL)
            else:
                b.configure(bg="#0b1625")

    def _register_window(self,key,win):
        if win is None or not win.winfo_exists(): return win
        old=self._windows_by_key.get(key)
        if old is not None and old is not win:
            try:
                if old.winfo_exists(): old.deiconify(); old.lift(); self.active_window=old; return old
            except Exception: pass
        self._windows_by_key[key]=win
        win._afold_app_key=key
        win._afold_shell=self
        win._afold_window_registered=True
        self._ensure_task_button(key)
        self.active_window=win
        def on_destroy(event=None, k=key, w=win):
            try:
                if self._windows_by_key.get(k) is w: self._windows_by_key.pop(k,None)
                if self.active_window is w: self.active_window=None
                # An unpinned task button behaves like Windows: it disappears when the app closes.
                if k not in set(self.store.config.get("taskbar_order", [])):
                    btn = self.taskbar_buttons.pop(k, None)
                    if btn is not None and btn.winfo_exists():
                        btn.destroy()
                self._refresh_taskbar_states()
            except Exception: pass
        win.bind("<Destroy>",on_destroy,add="+")
        self._refresh_taskbar_states()
        return win

    def task_press(self,e,key):
        self.task_drag_data=(key,e.x_root);self.task_dragging=False

    def task_drag(self,e,key):
        if not hasattr(self,"task_drag_data"):return
        if abs(e.x_root-self.task_drag_data[1])>6:self.task_dragging=True
        if not getattr(self,"task_dragging",False):return
        button=self.taskbar_buttons.get(key)
        if button is None:return
        holder=button.master;buttons=[b for b in holder.winfo_children() if hasattr(b,"_afold_key")]
        target=None
        for b in buttons:
            if b is not button:
                mid=b.winfo_rootx()+b.winfo_width()/2
                if e.x_root<mid:target=b;break
        if target:
            button.pack_forget();button.pack(side="left",before=target,padx=2,pady=5)

    def task_release(self,e,key):
        try:
            if getattr(self,"task_dragging",False):
                holder=self.taskbar_buttons[key].master
                order=[b._afold_key for b in holder.winfo_children() if hasattr(b,"_afold_key")]
                pinned=set(self.store.config.get("taskbar_order",[]))
                self.store.config["taskbar_order"]=[k for k in order if k in pinned]
                self.store.save()
            else:
                self._taskbar_activate(key)
        except Exception as exc:
            self._report_app_error(self.app_map.get(key).name if key in self.app_map else key, exc)
        finally:
            self.task_drag_data=None;self.task_dragging=False

    def _taskbar_activate(self,key):
        win=self._windows_by_key.get(key)
        if win is not None and win.winfo_exists():
            if getattr(win,"_afold_animating",False): return
            if not getattr(win,"_afold_visible",True):
                win.deiconify()
            elif self.active_window is win:
                win.iconify()
            else:
                win.lift();win._raise_taskbar();self.active_window=win;self._refresh_taskbar_states()
            return
        app=self.app_map.get(key)
        if app is not None:self._desktop_open(app)

    def rebuild_desktop(self):
        """Rebuild the desktop visual layer after personalization changes."""
        if not hasattr(self, "desktop") or not self.desktop.winfo_exists():
            return
        for w in getattr(self, "desktop_icon_widgets", []):
            try: w.destroy()
            except Exception: pass
        if getattr(self, "canvas", None) is not None:
            try: self.canvas.destroy()
            except Exception: pass
        if getattr(self, "taskbar", None) is not None:
            try: self.taskbar.destroy()
            except Exception: pass
        self.build_wallpaper(); self.build_icons(); self.build_taskbar()
        # Re-attach the desktop context menu after every rebuild.
        self.desktop.bind("<Button-3>", self.desktop_context)
        self.canvas.bind("<Button-3>", self.desktop_context)
        if self.start_menu is not None and self.start_menu.winfo_exists():
            try: self.start_menu.lift()
            except Exception: pass

    def toggle_start(self):
        if self.start_menu and self.start_menu.winfo_exists():self.start_menu.destroy();self.start_menu=None
        else:self.start_menu=StartMenu(self)
    def update_clock(self):
        if not self.root.winfo_exists():return
        self.clock.set(datetime.now().strftime("%H:%M\n%d.%m.%Y"));self.root.after(1000,self.update_clock)
