    def _embedded_app(self, title, module_name, class_name, width, height):
        """Run Word/Excel inside an AFold internal window (no native window)."""
        try:
            import importlib.util
            file_path = ROOT / (module_name + '.py')
            if not file_path.exists():
                raise FileNotFoundError(str(file_path))
            spec = importlib.util.spec_from_file_location(module_name, file_path)
            if spec is None or spec.loader is None:
                raise ImportError('Не удалось загрузить модуль ' + module_name)
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            win = LiquidWindow(self.root, title, width, height)
            win.titlebar(title)
            content = tk.Frame(win, bg=Glass.BG)
            content.pack(fill='both', expand=True)
            app_root = EmbeddedRoot(content, win)
            cls = getattr(mod, class_name)
            win._embedded_app_instance = cls(app_root)
            win._embedded_module = mod
            win.lift(); win._raise_taskbar()
            return win
        except ModuleNotFoundError as e:
            messagebox.showerror(title, f'Не хватает библиотеки: {e.name}\n\nДля Word/Excel запусти install_word_dependencies.bat.', parent=self.root)
        except Exception as e:
            import traceback
            try: (ROOT / 'afold_runtime_error.log').write_text(traceback.format_exc(), encoding='utf-8')
            except Exception: pass
            messagebox.showerror(title, f'Ошибка запуска приложения:\n{type(e).__name__}: {e}\n\nПодробности: afold_runtime_error.log', parent=self.root)
        return None

